      if (glow && this.gl) { v.glow = v.glowDay = this.texture(glow); }
      const winBox = win && this.gl ? Compositor.maskBox(win) : null;   // no window in this view (the phone rail): no video
      if (winBox) { v.win = this.texture(win); v.winBox = winBox; }
