        const c = Compositor.scratch(w, h); const g = c.getContext('2d');
        g.clearRect(0, 0, w, h); g.drawImage(img, 0, 0, Math.round((r[2] - r[0]) * k), Math.round((r[3] - r[1]) * k));
        gl.texSubImage2D(gl.TEXTURE_2D, 0, x, y, gl.RGBA, gl.UNSIGNED_BYTE, c);
